INSERT INTO "Experience" ("id","companyZh","companyEn","roleZh","roleEn","locationZh","locationEn","startDate","endDate","summaryZh","summaryEn","highlightsZh","highlightsEn","sortOrder") VALUES(3,'華碩電腦股份有限公司','ASUSTeK Computer Inc.','後端工程師','Backend Engineer','台灣','Taiwan','2023-08-01T00:00:00.000Z','2026-03-31T00:00:00.000Z','我是一名以 PHP 為主要開發語言的後端工程師，具備電商系統、第三方服務串接及正式環境維護經驗。過去曾參與 ASUS Store 多國電商平台的開發與維護，服務站點包含台灣、美國、加拿大、墨西哥、馬來西亞、菲律賓、土耳其，工作內容涵蓋 Commerce、Payment、Logistics 與 Data 等領域。','I am a backend engineer specializing in PHP, with practical experience in e-commerce systems, third-party service integration, and production environment maintenance. I previously participated in the development and maintenance of ASUS Store''s multinational e-commerce platforms, supporting markets including Taiwan, the United States, Canada, Mexico, Malaysia, the Philippines, and Turkey, across Commerce, Payment, Logistics, and Data domains.','["商品、購物車、結帳、訂單、會員與紅利點數（Reward Points）等電商核心模組的功能開發與既有系統維護","串接 Apple Pay、Google Pay、Stripe、藍新金流、GogoPay、Zingala 等第三方金流服務，並開發訂單分期付款（Installment）流程","開發 UPS 定點取貨（Pickup）與物流配送相關流程，處理收件地址欄位驗證與整合","依加拿大、土耳其、菲律賓、墨西哥等市場的地址規則與結帳流程差異，調整並維護地區性結帳邏輯","撰寫 SQL 查詢與 CTE 報表，處理跨時區資料轉換需求，支援營運與財務報表產出","在 MariaDB、OpenSearch、Queue / Job、Docker、WSL2 組成的開發與資料平台上進行功能開發、除錯與環境維護","主動追蹤並排除橫跨結帳、金流、物流與資料流程的正式環境異常問題"]','["Developed and maintained core e-commerce modules including Product, Cart, Checkout, Order, Membership, and Reward Points","Integrated third-party payment gateways including Apple Pay, Google Pay, Stripe, NewebPay, GogoPay, and Zingala, and built installment payment workflows","Built UPS pickup and shipping-related workflows, and handled shipping address field validation and integration","Adjusted and maintained region-specific checkout logic to account for address rules and checkout differences across markets including Canada, Turkey, the Philippines, and Mexico","Wrote SQL queries and CTE-based reports, and handled cross-timezone data conversion to support operational and financial reporting","Developed, debugged, and maintained services on a data and development platform built on MariaDB, OpenSearch, Queue/Job processing, Docker, and WSL2","Proactively investigated and resolved production issues across checkout, payment, logistics, and data workflows"]',0);
CREATE TABLE IF NOT EXISTS "Project" (
    "id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
    "nameZh" TEXT NOT NULL,
    "nameEn" TEXT NOT NULL,
    "summaryZh" TEXT NOT NULL,
    "summaryEn" TEXT NOT NULL,
    "highlightsZh" TEXT NOT NULL,
    "highlightsEn" TEXT NOT NULL,
    "techStack" TEXT,
    "link" TEXT,
    "imageUrl" TEXT,
    "sortOrder" INTEGER NOT NULL DEFAULT 0
, "categoryZh" TEXT, "categoryEn" TEXT, "subtitleZh" TEXT, "subtitleEn" TEXT, "githubUrl" TEXT, "featured" BOOLEAN NOT NULL DEFAULT false);
INSERT INTO "Project" ("id","nameZh","nameEn","summaryZh","summaryEn","highlightsZh","highlightsEn","techStack","link","imageUrl","sortOrder","categoryZh","categoryEn","subtitleZh","subtitleEn","githubUrl","featured") VALUES(9,'TaskFlow','TaskFlow','我自行設計並開發 TaskFlow，一套 Local-first 的 AI Engineering Workflow Platform，讓 AI 代理能依循「需求 → 規劃 → 人工核准 → 實作 → Git Commit → 獨立驗證 → 修正 → 部署驗證 → 合併 → 結案」的完整流程執行工程任務，同時保留人在迴圈中的關鍵審核點。','I independently designed and built TaskFlow, a local-first AI Engineering Workflow Platform that lets AI agents carry out engineering tasks through a full Requirement → Planning → Human Approval → Implementation → Git Commit → Independent Validation → Repair → Deployment Validation → Merge → Close pipeline, while keeping a human-in-the-loop at key review points.','["以 Git worktree 隔離每個任務的工作副本，避免任務間互相干擾","導入測試基準線（test baseline）與差異比對，區分既有失敗與本次修改造成的迴歸","整合瀏覽器驗證（browser validation）與部署驗證流程，確保交付前通過可觀察的檢查","設計 Preview 生命週期管理，涵蓋啟動、健康檢查、驗證到結束的完整流程","透過 LINE 與 Cloudflare 建置遠端任務通知與觸發管道","以結構化 AI 輸出（structured AI output）串接規劃、執行、驗證與修正各階段"]','["Isolated each task in its own Git worktree to prevent cross-task interference","Introduced test baselines and regression comparison to distinguish pre-existing failures from newly introduced regressions","Integrated browser validation and deployment validation into the pipeline to ensure observable checks before delivery","Designed preview runtime lifecycle management covering startup, health checks, validation, and teardown","Built remote task notification and triggering via LINE and Cloudflare","Connected planning, execution, validation, and repair stages through structured AI output"]','["AI Agent Workflow","Human-in-the-loop","Git Worktree","Test Baseline","Regression Comparison","Browser Validation","Preview Lifecycle","Process Management","LINE Integration","Cloudflare","SQLite","Structured AI Output"]',NULL,NULL,0,'AI 工程平台','AI Engineering Platform','AI 工程工作流平台','AI Engineering Workflow Platform','https://github.com/LuckyFSChen/Taskflow',1);
INSERT INTO "Project" ("id","nameZh","nameEn","summaryZh","summaryEn","highlightsZh","highlightsEn","techStack","link","imageUrl","sortOrder","categoryZh","categoryEn","subtitleZh","subtitleEn","githubUrl","featured") VALUES(10,'DineFlow','DineFlow','我自行規劃並開發餐飲點餐 SaaS 系統 DineFlow。透過這個專案，我累積了從資料庫設計、內用點餐流程、購物車與結帳、多店家架構到系統部署的完整經驗，也開始從使用者流程與產品角度思考系統設計。','I independently planned and developed DineFlow, a SaaS-based restaurant ordering system. Through this project, I gained end-to-end experience across database design, dine-in ordering flow, cart and checkout, multi-store architecture, and system deployment, and strengthened my ability to consider system design from both user experience and product perspectives.','["以 Laravel 開發，設計 Store → Tables / Categories / Products → Orders → Order Items 的資料模型","實作內用點餐流程：QR Code 掃碼 → 選桌 → 瀏覽菜單 → 加入購物車 → 結帳 → 建立訂單","支援多店家（multi-store）架構，讓不同店家的菜單、桌位與訂單彼此獨立","規劃 SaaS 化的商業模式與商家後台，並以 MVP 精神優先驗證核心點餐流程","將系統部署至 GCP 雲端主機，處理環境設定與上線流程"]','["Built with Laravel; designed a data model of Store → Tables / Categories / Products → Orders → Order Items","Implemented the dine-in ordering flow: QR code scan → table selection → menu browsing → cart → checkout → order creation","Supported a multi-store architecture, keeping each store’s menu, tables, and orders independent","Planned the SaaS business model and merchant admin panel, prioritizing an MVP to validate the core ordering flow first","Deployed the system to a GCP cloud server, handling environment setup and release"]','["Laravel","MySQL","Cart","Checkout","Multi-store","SaaS","GCP"]',NULL,NULL,1,'SaaS 產品','SaaS Product','餐飲點餐 SaaS 系統','Restaurant Ordering SaaS',NULL,1);
INSERT INTO "Project" ("id","nameZh","nameEn","summaryZh","summaryEn","highlightsZh","highlightsEn","techStack","link","imageUrl","sortOrder","categoryZh","categoryEn","subtitleZh","subtitleEn","githubUrl","featured") VALUES(11,'Lucky IDV','Lucky IDV','這個作品集網站本身也是我的專案之一。它是一套資料驅動（data-driven）的全端工程作品集平台，所有經歷、專案與工程案例都存放在資料庫中並透過後台管理，而不是寫死在頁面裡的靜態履歷。','This portfolio website is itself one of my projects. It is a data-driven, full-stack engineering portfolio platform where all experience, project, and engineering case content is stored in a database and managed through an admin panel, rather than hard-coded into static resume pages.','["前端以 Vue 3 與 TypeScript 建置，支援 zh-TW / EN 雙語系（i18n）","設計 Prisma 資料模型，將經歷、專案、工程案例、技能與證照抽象為結構化內容","開發後台管理介面與對應 API，支援內容的新增、編輯與排序","部署於 Cloudflare，並串接自訂網域"]','["Built the frontend with Vue 3 and TypeScript, supporting zh-TW / EN bilingual content (i18n)","Designed a Prisma data model that abstracts experience, projects, engineering cases, skills, and certifications into structured content","Developed the admin management interface and corresponding APIs for creating, editing, and reordering content","Deployed on Cloudflare with a custom domain"]','["Vue 3","TypeScript","i18n","Prisma","Admin","API","Cloudflare"]','https://taskflow.lucky0504.idv.tw/',NULL,2,'全端工程平台','Full-stack Engineering Platform','全端工程作品集平台','Full-stack Engineering Portfolio Platform','https://github.com/LuckyFSChen/Lucky-idv',1);
INSERT INTO "Project" ("id","nameZh","nameEn","summaryZh","summaryEn","highlightsZh","highlightsEn","techStack","link","imageUrl","sortOrder","categoryZh","categoryEn","subtitleZh","subtitleEn","githubUrl","featured") VALUES(12,'Wings of the Hollow','Wings of the Hollow','利用 Godot 引擎開發的 2D 平台動作遊戲專案，涵蓋玩法規劃、角色動畫狀態機與遊戲機制設計，是我在工程之外探索遊戲開發的個人專案。','A 2D platform action game project built with the Godot engine, covering gameplay planning, character animation state machines, and game mechanics design. A personal project exploring game development outside of my main engineering work.','["以 Godot 引擎開發 2D 平台動作遊戲","規劃核心玩法與關卡設計方向","實作角色動畫狀態機（animation states）","設計並調整遊戲機制（game mechanics）"]','["Developed a 2D platform action game using the Godot engine","Planned core gameplay and level design direction","Implemented character animation state machines","Designed and tuned game mechanics"]','["Godot","Gameplay Planning","Animation States","Game Mechanics"]',NULL,NULL,3,'其他專案','Other Projects','2D 平台動作遊戲專案','2D Platform Game Project',NULL,0);
