    "descriptionZh" TEXT,
    "descriptionEn" TEXT,
    "credential" TEXT,
    "issuedAt" DATETIME,
    "link" TEXT,
    "sortOrder" INTEGER NOT NULL DEFAULT 0
);
INSERT INTO "Certification" ("id","nameZh","nameEn","issuerZh","issuerEn","descriptionZh","descriptionEn","credential","issuedAt","link","sortOrder") VALUES(3,'ISO 27001:2022 資訊安全管理系統主導稽核員','ISO 27001:2022 Information Security Management System Lead Auditor','BSI 英國標準協會','BSI (British Standards Institution)','取得 CQI & IRCA 認證之 ISO 27001:2022 資訊安全管理系統主導稽核員資格，具備規劃與執行資訊安全稽核之能力。','Holds a CQI & IRCA certified ISO 27001:2022 Information Security Management System Lead Auditor qualification, with the ability to plan and conduct information security audits.','ENR-01584911','2024-09-06T00:00:00+00:00',NULL,0);
